import{_ as r,c as o,a2 as a,o as i}from"./chunks/framework.D7kq4b6j.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"docs/数据结构与算法/数据结构与算法/01- 第一章/01-算法的基本概念.md","filePath":"docs/数据结构与算法/数据结构与算法/01- 第一章/01-算法的基本概念.md","lastUpdated":1723995988000}'),n={name:"docs/数据结构与算法/数据结构与算法/01- 第一章/01-算法的基本概念.md"};function s(l,t,e,g,d,c){return i(),o("div",null,t[0]||(t[0]=[a('<h2 id="什么是算法" tabindex="-1">什么是算法 <a class="header-anchor" href="#什么是算法" aria-label="Permalink to &quot;什么是算法&quot;">​</a></h2><p>算法是一种解决特定问题的明确、有限、可执行的计算步骤序列。</p><h2 id="算法的五个特性" tabindex="-1">算法的五个特性 <a class="header-anchor" href="#算法的五个特性" aria-label="Permalink to &quot;算法的五个特性&quot;">​</a></h2><ul><li><strong>有穷性</strong>：一个算法必须执行有穷步后结束</li><li><strong>确定性</strong>：对于每种情况下所应执行的操作，在算法中都应该有确切的规定，不会产生二义性，使得算法的执行者和阅读者都能明确其含义以及如何执行。</li><li><strong>可行性</strong>：算法中的所有操作都可以通过已经实现的基本操作运算执行有限次来实现</li><li><strong>输入</strong>：一个算法应该有0个、一个或多个输入</li><li><strong>输出</strong>：一个算法应该有一个或多个输出。</li></ul><h2 id="好算法的特质" tabindex="-1">好算法的特质 <a class="header-anchor" href="#好算法的特质" aria-label="Permalink to &quot;好算法的特质&quot;">​</a></h2><ol><li><strong>效率</strong>（Efficiency）：算法应该在<strong>时间</strong>和<strong>空间</strong>复杂度（特别是时间复杂度）上表现良好。理想情况下，算法的时间复杂度应该尽可能低，空间复杂度也应该尽可能低，以处理大规模数据和实时环境。</li><li><strong>正确性</strong>（Correctness）：算法必须遵循逻辑严谨，处理所有可能的情况时都能得到正确的结果。通常会有多重测试和验证来确保这一点。</li><li><strong>可读性</strong>（Readability）：良好的算法应该易于理解，清晰明了，逻辑结构清晰，语法简洁，注释到位，这对于代码的后期维护非常重要。</li><li><strong>可维护性</strong>（Maintainability）：好算法应具有良好的结构，结构组织良好，模块化，减少代码的耦合度，使得修改和扩展变得简单。</li><li><strong>通用性</strong>（Generality）：算法应该尽量避免与特定编程语言或实现细节相关，适用于不同的编程语言和平台。</li><li><strong>适应性</strong>（Adaptability）：对于不同的输入规模和特点，好算法能进行有效的调整，并确保在任何情况下都能保持性能稳定。</li><li><strong>稳定性</strong>（Stability）：即使在输入、环境变化或其他外部因素影响下，算法依然能够稳定工作，不会出现意外的行为或崩溃。</li><li><strong>可扩展性</strong>：好的算法应该允许容易地添加新的功能或修改现有的功能，而不会导致代码过度膨胀或结构混乱。</li></ol>',6)]))}const p=r(n,[["render",s]]);export{h as __pageData,p as default};
